DIAG = 'import json,re\nfrom pathlib import Path\nfrom datetime import datetime,timezone\nfrom sqlalchemy import select,text\nfrom sqlalchemy.orm import joinedload\nfrom app.db.session import SyncSessionLocal\nfrom app.models.database import Tender,Lot\nfrom app.core.config import settings\nfrom app.reports.review_dismissals import is_dismissed\nfrom app.reports.dashboard_eligibility import evaluate_dashboard_tender\nfrom app.reports.active_tenders import get_active_tenders,get_tender_dashboard,REPORT_STATUSES\nfrom app.sources.eis_freshness import eligibility\nfrom app.scoring.selection_policy import qualifies,mass_kg,piece_count,material_status\n\ndef val(x):return getattr(x,\'value\',x)\ndef safe(x):\n s=str(x or \'\')\n s=re.sub(r\'https?://[^\\s\\"\\x27<>]+\',\'[URL]\',s)\n s=re.sub(r\'(?i)(authorization|cookie|token|password|secret)\\s*[:=]\\s*\\S+\',r\'\\1=[hidden]\',s)\n return s[:1800]\ndef show(x):print(json.dumps(x,ensure_ascii=False,default=str),flush=True)\n\nwith SyncSessionLocal() as db:\n db.execute(text(\'SET TRANSACTION READ ONLY\'));db.execute(text("SET LOCAL statement_timeout = \'15000\'"))\n t=db.execute(select(Tender).where(Tender.source==\'gpb\',Tender.external_id==\'2077557\').options(joinedload(Tender.lots).joinedload(Lot.items))).unique().scalar_one_or_none()\n if t:\n  positions=[]\n  for lot in t.lots:\n   for p in lot.items:\n    row={\'product_name\':p.name,\'product_type\':p.product_type,\'alloy\':p.alloy,\'quantity\':p.quantity,\'unit\':p.unit,\'mass_kg\':p.mass_kg,\'can_supply\':p.can_supply}\n    positions.append(row)\n  checks={\'source\':\'gpb\',\'number\':\'2077557\',\'active\':t.is_active,\'deadline\':t.submission_deadline,\'dismissed\':is_dismissed(t.source,t.external_id),\'status\':val(t.status),\'processing_status\':val(t.processing_status),\'analysis_done\':t.analysis_done,\'score\':t.score,\'report_status_allowed\':t.status in REPORT_STATUSES,\'freshness_reason\':eligibility(t.source,t.submission_deadline,t.raw_payload,t.is_active)}\n  decision=evaluate_dashboard_tender({**checks,\'positions\':positions})\n  checks.update(position_gate=decision.eligible,position_gate_reason=decision.reason)\n  show({\'section\':\'GPB_CARD_GATES\',**checks})\n  show({\'section\':\'GPB_POSITION_GATES\',\'rows\':[{\'name\':p[\'product_name\'],\'quantity\':p[\'quantity\'],\'unit\':p[\'unit\'],\'mass_kg\':mass_kg(p),\'pieces\':piece_count(p),\'material\':material_status(p),\'qualifies\':qualifies(p)} for p in positions]})\n else:show({\'section\':\'GPB_CARD_GATES\',\'found\':False})\n db.rollback()\nrows=get_active_tenders();cards=get_tender_dashboard()\nshow({\'section\':\'GPB_REPORT_TRACE\',\'active_rows\':sum(str(r.get(\'external_id\'))==\'2077557\' and r.get(\'source\')==\'gpb\' for r in rows),\'suitable\':any(str(r.get(\'external_id\'))==\'2077557\' and r.get(\'source\')==\'gpb\' for r in cards)})\nroot=Path(settings.storage_path)\nfor source in [\'metal_it\',\'gpb\',\'glavstroy\',\'samolet\']:\n p=root/\'marketplace_primary\'/(source+\'.json\')\n if not p.exists():continue\n try:\n  d=json.loads(p.read_text());show({\'section\':\'HANDOFF_DETAILS\',\'source\':source,\'checked_at\':d.get(\'checked_at\'),\'status\':d.get(\'status\'),\'backlog_pending\':d.get(\'backlog_pending\'),\'failures\':[{k:safe(v) for k,v in r.items() if k in (\'number\',\'status\',\'phase\',\'error_type\',\'reason\')} for r in d.get(\'pipeline\') or [] if r.get(\'status\')==\'queue_error\']})\n except Exception as exc:show({\'section\':\'HANDOFF_DETAILS\',\'source\':source,\'error_type\':type(exc).__name__})\nprint(\'TARGETED_DIAGNOSTICS_READ_ONLY: no requeue, DB edits, HTTP, OCR or LLM\',flush=True)\n'
