import argparse,ast,hashlib,json,os,shutil,subprocess,tempfile,time
from pathlib import Path
from datetime import datetime,timezone

def run(cmd,**kwargs):return subprocess.run(cmd,check=True,**kwargs)
def digest(b):return hashlib.sha256(b).hexdigest()
def image_function(source):
 tree=ast.parse(source)
 nodes=[n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name=='extract_image']
 stores=[n for n in ast.walk(tree) if isinstance(n,ast.Name) and n.id=='extract_image' and isinstance(n.ctx,ast.Store)]
 if len(nodes)!=1 or stores or nodes[0].decorator_list:
  raise SystemExit('OCR_FUNCTION_LAYOUT_UNSUPPORTED: no files changed')
 return nodes[0]

def image_ast(node):
 # Formatting and the documentation string do not change function behavior.
 node=ast.parse(ast.unparse(node)).body[0]
 if node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):node.body=node.body[1:]
 return ast.dump(node,include_attributes=False)

def patch_image_only(current,desired):
 source=current.decode('utf-8')
 actual=image_function(source);old=image_function(OLD_IMAGE_SOURCE);new=image_function(desired)
 if image_ast(actual)==image_ast(new):return source
 if image_ast(actual)!=image_ast(old):
  print('OCR_CURRENT_SHA256:',digest(current),flush=True)
  print('OCR_CURRENT_FUNCTION:\n'+ast.get_source_segment(source,actual),flush=True)
  raise SystemExit('OCR_FUNCTION_VERSION_MISMATCH: no files changed; current function printed above')
 helpers=[n for n in ast.parse(source).body if isinstance(n,ast.FunctionDef) and n.name=='_ocr_image']
 if len(helpers)!=1 or len(helpers[0].args.args)<2 or helpers[0].args.args[1].arg!='page_number':
  raise SystemExit('OCR_HELPER_SIGNATURE_MISMATCH: no files changed')
 lines=source.splitlines(keepends=True)
 replacement=ast.get_source_segment(desired,new)+'\n'
 patched=''.join(lines[:actual.lineno-1])+replacement+''.join(lines[actual.end_lineno:])
 compile(patched,'app/ocr/pipeline.py','exec')
 return patched

def patch_known_function(current,desired,name,original):
 source=current.decode('utf8')
 def find(text):
  tree=ast.parse(text)
  body=tree.body
  parts=name.split('.')
  for part in parts[:-1]:
   classes=[n for n in body if isinstance(n,ast.ClassDef) and n.name==part]
   if len(classes)!=1:raise SystemExit('FUNCTION_LAYOUT_UNSUPPORTED: '+name)
   body=classes[0].body
  nodes=[n for n in body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==parts[-1]]
  if len(nodes)!=1:raise SystemExit('FUNCTION_LAYOUT_UNSUPPORTED: '+name)
  return nodes[0]
 actual=find(source);new=find(desired)
 originals=original if isinstance(original,(tuple,list)) else (original,)
 olds=[find(item) for item in originals]
 if image_ast(actual)==image_ast(new):return source
 if not any(image_ast(actual)==image_ast(old) for old in olds):raise SystemExit('FUNCTION_VERSION_MISMATCH: '+name+'; no files changed')
 lines=source.splitlines(keepends=True)
 start=min([actual.lineno]+[d.lineno for d in actual.decorator_list])-1
 newstart=min([new.lineno]+[d.lineno for d in new.decorator_list])-1
 newlines=desired.splitlines(keepends=True)
 patched=''.join(lines[:start])+''.join(newlines[newstart:new.end_lineno])+''.join(lines[actual.end_lineno:])
 compile(patched,name,'exec')
 return patched

def check_files(root):
 pending=[]
 for rel,expected,content in FILES:
  p=root/rel
  if p.is_symlink():raise SystemExit('SYMLINK_NOT_SUPPORTED: '+rel)
  current=p.read_bytes() if p.is_file() else None
  if rel in TEXT_PATCHES:
   if current is None:raise SystemExit('FILE_MISSING: '+rel+'; no files changed')
   text=current.decode('utf8')
   for before,after in TEXT_PATCHES[rel]:
    if text.count(after)==1:continue
    if text.count(before)!=1:raise SystemExit('TEXT_VERSION_MISMATCH: '+rel+'; no files changed')
    text=text.replace(before,after,1)
   if text.encode('utf8')!=current:pending.append((rel,text,current))
   continue
  if rel in FOCUSED_FUNCTIONS and current is not None:
   names,original=FOCUSED_FUNCTIONS[rel]
   names=names if isinstance(names,(tuple,list)) else (names,)
   desired=content;patched=current
   for name in names:patched=patch_known_function(patched,desired,name,original).encode('utf8')
   content=patched.decode('utf8')
   if patched!=current:pending.append((rel,content,current))
   continue
  if rel=='app/ocr/pipeline.py' and current is not None:
   content=patch_image_only(current,content)
   if content.encode('utf8')!=current:pending.append((rel,content,current))
   continue
  wanted=content.encode('utf8')
  if current==wanted:continue
  if (current is None and expected is not None) or (current is not None and digest(current) not in {expected,*ACCEPTED_PREVIOUS.get(rel,[])}):
   raise SystemExit('VERSION_MISMATCH: '+rel+'; no files changed. Send this line; do not bypass.')
  compile(content,rel,'exec')
  pending.append((rel,content,current))
 return pending

def atomic(path,data):
 path.parent.mkdir(parents=True,exist_ok=True)
 fd,tmp=tempfile.mkstemp(dir=path.parent,prefix=path.name+'.')
 try:
  with os.fdopen(fd,'wb') as f:f.write(data)
  if path.exists():shutil.copymode(path,tmp)
  os.replace(tmp,path)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)

def compare_network():
 for label,cmd in [('host',['python3','-']),('celery_discovery',['docker','compose','exec','-T','celery_discovery','python','-'])]:
  print('TENDER_PRO_NETWORK:',label,flush=True)
  try:
   run(cmd,input=NETWORK_PROBE,text=True,timeout=35)
  except subprocess.TimeoutExpired:
   print(json.dumps({'environment':label,'status':'probe_timeout','phase':'unknown; probe exceeded 35s'}),flush=True)
  except (OSError,subprocess.CalledProcessError) as exc:
   print(json.dumps({'environment':label,'status':'probe_unavailable','error_type':type(exc).__name__}),flush=True)
 print('NETWORK_COMPARE_FINISHED: no HTTP API, credentials, DB changes, queues, OCR or LLM',flush=True)

def check_tender_pro_public():
 try:
  run(['docker','compose','exec','-T','celery_discovery','python','-'],input=CHECK_TENDER_PRO_PUBLIC,text=True,timeout=90)
 except subprocess.TimeoutExpired:
  print('TENDER_PRO_PUBLIC_CHECK_TIMEOUT: completion not confirmed; no automatic retry',flush=True)
 except (OSError,subprocess.CalledProcessError) as exc:
  print('TENDER_PRO_PUBLIC_CHECK_UNAVAILABLE:',type(exc).__name__,flush=True)

def check_new_platforms():
 try:
  run(['docker','compose','exec','-T','celery_discovery','python','-'],input=CHECK_NEW_PLATFORMS,text=True,timeout=300)
 except subprocess.TimeoutExpired:
  print('NEW_PLATFORMS_CHECK_TIMEOUT: completion/report not confirmed; no automatic retry',flush=True)
 except (OSError,subprocess.CalledProcessError) as exc:
  print('NEW_PLATFORMS_CHECK_UNAVAILABLE:',type(exc).__name__,flush=True)

def main():
 parser=argparse.ArgumentParser(description='Install verified public developer adapters and repair discovery reporting. Existing OCR/LLM, no duplicate models.')
 parser.add_argument('--check-only',action='store_true',help='check source versions without Docker or writes')
 parser.add_argument('--diagnose-only',action='store_true',help='read GPB gate and saved handoff failures; no HTTP, tasks or DB writes')
 parser.add_argument('--guide',action='store_true',help='print the integrated Russian deployment guide')
 parser.add_argument('--status',action='store_true',help='read installed source schedules and reports; no tasks or LLM')
 parser.add_argument('--run-gpb',action='store_true',help='after successful installation queue one bounded GPB collection')
 parser.add_argument('--recover-gpb-large',action='store_true',help='install and resume saved texts of GPB 2081355 once; no OCR/downloads')
 parser.add_argument('--probe-tender-pro',action='store_true',help='one API request and bounded TLS checks, no business tasks')
 parser.add_argument('--audit-backlog',action='store_true',help='read GPB/Bidzaar candidates and worker states')
 parser.add_argument('--check-access',action='store_true',help='install then run access probe and backlog audit')
 parser.add_argument('--compare-tender-pro-network',action='store_true',help='compare DNS/TCP/TLS on host and worker container; no API requests')
 parser.add_argument('--run-priority',action='store_true',help='install, compare network and queue one GPB/Bidzaar collection each')
 parser.add_argument('--check-tender-pro-public',action='store_true',help='check public keyword search without API keys; save diagnostic report only')
 parser.add_argument('--check-new-platforms',action='store_true',help='read-only public onboarding checks for Roseltorg/Sberbank-AST/RTS')
 args=parser.parse_args();root=Path.cwd()
 inspections=(args.guide,args.status,args.check_only,args.diagnose_only,args.probe_tender_pro,args.audit_backlog,args.compare_tender_pro_network,args.check_tender_pro_public,args.check_new_platforms)
 actions=(args.run_gpb,args.recover_gpb_large,args.check_access,args.run_priority)
 if sum(map(bool,inspections))>1 or sum(map(bool,actions))>1 or (any(inspections) and any(actions)):
  parser.error('Choose one inspection mode, or installation with one optional action')
 if args.guide:print(GUIDE);return
 if not (root/'app/workers/celery_app.py').is_file():raise SystemExit('Run from ~/LLM-assistant/tender-ai-platform-v6.2')
 if args.check_new_platforms:
  check_new_platforms();return
 if args.check_tender_pro_public:
  check_tender_pro_public();return
 if args.compare_tender_pro_network:
  compare_network();return
 if args.probe_tender_pro:
  run(['docker','compose','exec','-T','celery_discovery','python','-'],input=PROBE_TENDER_PRO,text=True,timeout=90);return
 if args.audit_backlog:
  run(['docker','compose','exec','-T','celery_discovery','python','-'],input=AUDIT_BACKLOG,text=True,timeout=90);return
 if args.status:
  run(['docker','compose','exec','-T','app','python','-'],input=STATUS,text=True,timeout=90);return
 if args.diagnose_only:
  run(['docker','compose','exec','-T','app','python','-'],input=DIAG,text=True,timeout=90);return
 required=('app/sources/gpb/adapter.py','app/sources/gpb/card.py','app/sources/gpb/relevance.py',
           'app/sources/gpb/transport.py','app/sources/gpb/archives.py','app/sources/gpb/document_cache.py',
           'app/sources/pipeline_recovery.py','app/workers/tasks_parsing.py','app/workers/tasks_scoring.py')
 missing=[p for p in required if not (root/p).is_file()]
 if missing:raise SystemExit('EXISTING_V62_REQUIRED: '+', '.join(missing)+'; no files changed')
 pending=check_files(root)
 print('SOURCE_GUARDS_OK; CHANGES:',len(pending),flush=True)
 if args.check_only:return
 # Never replace the already installed dashboard policy with an older image's files.
 ui=(root/'app/static/index.html').read_text()
 gate=(root/'app/reports/dashboard_eligibility.py').read_text()
 if 'allTenders = main.tenders;' not in ui or "'manual_review', 'needs_clarification'" not in gate:
  raise SystemExit('DASHBOARD_POLICY_NOT_CURRENT: no changes; update repository checkout from installed app before rebuilding')
 # Diagnose current card without reviving manually dismissed records.
 diag=run(['docker','compose','exec','-T','app','python','-'],input=DIAG,text=True,timeout=90)
 backup=root/'backups'/('sources-connect-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
 try:
  for rel,content,current in pending:
   if current is not None:atomic(backup/rel,current)
  if pending:
   atomic(backup/'manifest.json',json.dumps({'files':[{'path':rel,'new_file':old is None} for rel,_,old in pending]},indent=2).encode())
   for rel,content,current in pending:atomic(root/rel,content.encode('utf8'))
   print('BACKUP:',backup,flush=True)
  run(['docker','compose','build','app','celery_worker','celery_discovery','celery_beat'])
  run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input=TESTS,text=True,timeout=120)
 except BaseException:
  for rel,_,old in pending:
   if old is None:(root/rel).unlink(missing_ok=True)
   else:atomic(root/rel,old)
  print('BUILD_OR_TEST_FAILED: source restored; running services were not restarted',flush=True)
  raise
 # Ask workers to finish their current tasks; never use SIGKILL/queue purge.
 running=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True).stdout.split()
 services=[s for s in ('celery_beat','celery_discovery','celery_worker') if s in running]
 ids=[]
 for s in services:ids.extend(run(['docker','compose','ps','-q',s],capture_output=True,text=True).stdout.split())
 if services:
  print('Waiting for worker warm shutdown; existing tasks may finish.',flush=True)
  run(['docker','compose','kill','--signal','SIGTERM',*services])
  until=time.monotonic()+300
  while ids:
   states=run(['docker','inspect','--format','{{.State.Running}}',*ids],capture_output=True,text=True).stdout.split()
   if all(s=='false' for s in states):break
   if time.monotonic()>until:
    raise SystemExit('WARM_SHUTDOWN_PENDING: no forced stop. Let active tasks finish, then rerun this same installer.')
   time.sleep(3)
 run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery','celery_beat'])
 run(['docker','compose','exec','-T','celery_discovery','python','-'],input=VERIFY,text=True,timeout=60)
